import{_ as e,o as i,c as n,a1 as t}from"./chunks/framework.CblolBb6.js";const u=JSON.parse('{"title":"Hari 1 - Dasar GIS, QGIS, dan Peta 2D","description":"","frontmatter":{},"headers":[],"relativePath":"hari-1/index.md","filePath":"hari-1/index.md"}'),r={name:"hari-1/index.md"};function l(d,a,s,p,k,m){return i(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="hari-1-dasar-gis-qgis-dan-peta-2d" tabindex="-1">Hari 1 - Dasar GIS, QGIS, dan Peta 2D <a class="header-anchor" href="#hari-1-dasar-gis-qgis-dan-peta-2d" aria-label="Permalink to &quot;Hari 1 - Dasar GIS, QGIS, dan Peta 2D&quot;">​</a></h1><p>Hari pertama membangun dua hal sekaligus: pemahaman tentang apa yang sedang dikerjakan, dan perkakas untuk mengerjakannya. Sesi pagi menjelaskan GIS serta alur kerja WebGIS, lalu peserta mengolah data spasial di QGIS. Sesi siang menurunkan data itu ke web, mulai dari HTML/CSS/JavaScript sampai menampilkan peta di browser dengan Leaflet.</p><p>Hari ini juga menjadi titik masuk untuk menyiapkan lingkungan kerja: Visual Studio Code, Node.js, Next.js, dan Git.</p><h2 id="jadwal-hari-1" tabindex="-1">Jadwal Hari 1 <a class="header-anchor" href="#jadwal-hari-1" aria-label="Permalink to &quot;Jadwal Hari 1&quot;">​</a></h2><p>Mengacu pada susunan acara pelatihan periode 15 sampai 18 September 2026.</p><table tabindex="0"><thead><tr><th>Waktu</th><th>Kegiatan</th><th>Materi di halaman ini</th></tr></thead><tbody><tr><td>09.00 - 10.00</td><td>Dasar-dasar GIS, jenis data GIS, sistem koordinat dan transformasi. Alur kerja WebGIS dan komponennya</td><td>Belum tersedia</td></tr><tr><td>10.15 - 12.00</td><td>Dasar QGIS, digitasi, pengisian atribut, styling data, layanan WFS, WMS, WMTS, WCS</td><td>Belum tersedia</td></tr><tr><td>13.00 - 14.00</td><td>Dasar HTML, CSS, JS dan pengenalan Leaflet</td><td><a href="#peta-2d-dengan-leaflet">Peta 2D dengan Leaflet</a></td></tr><tr><td>14.00 - 15.00</td><td>Praktik 2: membuat file HTML, menampilkan peta Leaflet, data lokal dan OGC service, widget Leaflet</td><td><a href="#peta-2d-dengan-leaflet">Peta 2D dengan Leaflet</a></td></tr><tr><td>15.15 - 16.00</td><td>Penjelasan framework, package pendukung (Leaflet, Cesium, Material UI), GitHub</td><td><a href="#persiapan-lingkungan">Persiapan Lingkungan</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Materi teori dan QGIS belum tersedia</p><p>Dua blok pertama Hari 1 (09.00 - 12.00) belum punya berkas materi di repositori ini. Sesi teori dasar GIS dan praktik QGIS saat ini masih disampaikan langsung oleh instruktur melalui slide, bukan melalui halaman ini. Halaman ini akan diperbarui begitu materinya tersedia.</p></div><h2 id="persiapan-lingkungan" tabindex="-1">Persiapan Lingkungan <a class="header-anchor" href="#persiapan-lingkungan" aria-label="Permalink to &quot;Persiapan Lingkungan&quot;">​</a></h2><p>Peserta menyiapkan perkakas sebelum menulis kode. Ada dua tahap:</p><ol><li><a href="/Pelatihan-WebGIS-BIG/hari-1/persiapan-lingkungan/instalasi-aplikasi.html">Instalasi Aplikasi</a> - memasang Visual Studio Code, Git, dan Node.js.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-1/persiapan-lingkungan/konfigurasi-framework.html">Persiapan dan Konfigurasi Framework</a> - membuat folder proyek, menginisialisasi Next.js, menghubungkan proyek ke repositori GitHub, dan menjalankan aplikasi di <code>localhost</code>.</li></ol><h2 id="peta-2d-dengan-leaflet" tabindex="-1">Peta 2D dengan Leaflet <a class="header-anchor" href="#peta-2d-dengan-leaflet" aria-label="Permalink to &quot;Peta 2D dengan Leaflet&quot;">​</a></h2><p>Empat praktik membangun peta 2D secara bertahap. Mulai dari peta kosong, menambah layer, sampai mengubah tampilan layer lewat JavaScript.</p><ol><li><a href="/Pelatihan-WebGIS-BIG/hari-1/peta-2d-leaflet/peta-awal.html">Perancangan dan Pembangunan Awal Peta 2D</a> - memasang Leaflet di dalam Next.js dan menampilkan peta dasar.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-1/peta-2d-leaflet/layer-geojson-kml-wms.html">Menampilkan Layer GeoJSON, KML dan WMS Geoserver</a> - menambahkan layer vektor dan layer dari layanan peta.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-1/peta-2d-leaflet/data-raster.html">Menampilkan Data Raster</a> - menampilkan data raster seperti GeoTIFF.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-1/peta-2d-leaflet/styling-layer.html">Styling Layer Dengan Javascript</a> - mengatur warna, ukuran, dan popup tiap layer.</li></ol><h2 id="yang-perlu-disiapkan-peserta" tabindex="-1">Yang Perlu Disiapkan Peserta <a class="header-anchor" href="#yang-perlu-disiapkan-peserta" aria-label="Permalink to &quot;Yang Perlu Disiapkan Peserta&quot;">​</a></h2><ul><li>Node.js dan npm, dipasang mengikuti <a href="/Pelatihan-WebGIS-BIG/hari-1/persiapan-lingkungan/instalasi-aplikasi.html">Instalasi Aplikasi</a>.</li><li>Akun GitHub, dipakai pada <a href="/Pelatihan-WebGIS-BIG/hari-1/persiapan-lingkungan/konfigurasi-framework.html">Persiapan dan Konfigurasi Framework</a>.</li><li>Berkas data spasial dari instruktur, dipakai pada praktik QGIS dan pada praktik layer peta.</li></ul><h2 id="hasil-akhir-hari-1" tabindex="-1">Hasil Akhir Hari 1 <a class="header-anchor" href="#hasil-akhir-hari-1" aria-label="Permalink to &quot;Hasil Akhir Hari 1&quot;">​</a></h2><p>Di akhir hari, peserta memiliki proyek Next.js yang berjalan di perangkat sendiri dan menampilkan peta 2D berisi layer data spasial, dengan tampilan layer yang sudah diatur lewat JavaScript.</p>',17)])])}const o=e(r,[["render",l]]);export{u as __pageData,o as default};
